INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:75','mayalex_normativos','10_LEYES_REGLAMENTOS','tienen el carácter de impuestos municipales, los siguientes:

1) Bienes Inmuebles;
2) Personal;
3) Industria, Comercio y Servicios;

4) Extracción y Explotación de Recursos, y;
5) Pecuarios.','75','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":101,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"25ac56c27167b7050e35efec282241755c55abe11a9dbf65e3d232d1e9f324cd","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 177-91","decretos":["177-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','75','25ac56c27167b7050e35efec282241755c55abe11a9dbf65e3d232d1e9f324cd','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:76','mayalex_normativos','10_LEYES_REGLAMENTOS','el Impuesto sobre Bienes Inmuebles se pagará anualmente, aplicando una tarifa de hasta L.3.50 por millar, tratándose de bienes inmuebles urbanos y hasta de L.2.50 por millar, en caso de inmuebles rurales. La tarifa aplicable la fijará la Corporación Municipal, pero en ningún caso los aumentos serán mayores a
L.0.50 por millar, en relación a la tarifa vigente, la cantidad a pagar se calculará de acuerdo a su valor catastral y en su defecto, al valor declarado.

El valor catastral podrá ser ajustado en los años terminados en (0) cero y en (5) cinco, siguiendo los criterios siguientes:

a) Uso de suelo;
b) Valor del Mercado;
c) Ubicación, y;
d) Mejoras

El Impuesto se cancelará en el mes de Agosto de cada año, aplicándose en caso de mora, un recargo de dos por ciento (2%) mensual, calculado sobre la cantidad del impuesto a pagar, excepto en el año de 1995.

Están exentos del pago de este impuesto10:

a) Los inmuebles destinados para habitación de su propietario, así:

1. En cuanto a los primeros CIEN MIL LEMPIRAS (L.100,000.00) de su valor catastral registrado o declarado en los municipios de 300.001 habitantes en adelante.
2. En cuanto a los primeros SESENTA MIL LEMPIRAS (L.60,000.00) de su valor catastral registrado o declarado en los municipios con 75.000 a 300.000 habitantes.
3. En cuanto a los primeros VEINTE MIL LEMPIRAS (L.20,000.00) de su valor catastral registrado o declarado en los municipios de hasta 75.000 habitantes.

b) Los bienes del Estado;
c) Los templos destinados a cultos religiosos y sus centros parroquiales;
ch) Los centros de educación gratuita o sin fines de lucro, los de asistencia o previsión social y los pertenecientes a las organizaciones privadas de desarrollo, calificados en cada caso, por la Corporación Municipal y;
d) Los centros para exposiciones industriales, comerciales y agropecuarias, pertenecientes a instituciones sin fines de lucro calificados por la Corporación Municipal.','76','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":102,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"94844eae0c35f08467f8f3a31f4bdb70f4892bfcc92b1be6096b3c18929d17a0","ubicacion":[],"constancias":[{"nota":8,"tipo":"REFORMA","texto":"Mediante Decreto 124-95 se estableció lo siguiente: Artículo 3. La determinación de los valores correspondientes a 1995, al tenor de lo dispuesto en el artículo 76 reformado, de la Ley de Municipalidades, deberán concertarse previamente con los diferentes sectores sociales y económicos de sus respectivas jurisdicciones, en un plazo de (90) días contados a partir de la entrada en vigencia del presente Decreto. Para los años subsiguientes la concertación de estos mismos valores deberá efectuarse dentro de un término de noventa (90) días antes de la fecha de la aprobación del presupuesto de cada municipalidad. Artículo 4. Transcurrido el período de concertación a que se refiere el párrafo primero del Artículo 3, los contribuyentes estarán sujetos a los créditos y débitos resultantes de los valores catastrales concertados; contando con un plazo de treinta (30) días a para realizar el pago respectivo o reclamar las devoluciones correspondientes. No deberán efectuar ningún pago quienes se encuentren comprendidos en los rangos de excepciones del Artículo 76 reformado, de la Ley de Municipalidades.","decretos":["124-95"]},{"nota":9,"tipo":"REFERENCIA","texto":"Debe aplicarse lo establecido por el Artículo 109 de esta Ley.","decretos":[]},{"nota":11,"tipo":"INTERPRETACION_AUTENTICA","texto":"Según Decreto 171-98 se estableció lo siguiente: Artículo 4. Interpretar el literal b) del artículo 76 de la Ley de Municipalidades el que fue reformado mediante Decreto No. 124-95 de fecha 8 de agosto de 1995, en el sentido de que los particulares que ocupen, posean, exploten, usen o usufructúen bienes estatales o ejidales no están exonerados del pago del Impuesto Sobre Bienes Inmuebles.","decretos":["171-98","124-95"]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 124-95","decretos":["124-95"]},{"nota":null,"tipo":"INTERPRETACION_AUTENTICA","texto":"Interpretado","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:2"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','76','94844eae0c35f08467f8f3a31f4bdb70f4892bfcc92b1be6096b3c18929d17a0','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:77','mayalex_normativos','10_LEYES_REGLAMENTOS','. Toda persona natural pagará anualmente un impuesto personal único, sobre sus ingresos anuales, en el municipio en que lo perciba, de acuerdo a la tabla siguiente:

DE LPS. HASTA LPS. MILLAR 1 5.000 1.50 5.001 10.000 2.00 10.001 20.000 2.50 20.001 30.000 3.00 30.001 50.000 3.50 50.001 75.000 3.75 75.00 1 100.000 4.00 100.001 150.000 5.00 150.001 o más 5.25

Las personas a que se refiere el presente Artículo deberán presentar a más tardar en el mes de abril de cada año, una declaración jurada, de los ingresos percibidos durante el año calendario anterior, en los formularios que para tal efecto proporcionará gratuitamente la Municipalidad.

El hecho de que el contribuyente no se haya provisto del formulario, no lo exime de la obligación de hacer la declaración, la que en este caso podrá presentar en papel común con los requisitos contenidos en el mismo formulario.

La presentación de la declaración fuera del plazo establecido en este Artículo, se sancionará con multa equivalente al diez por ciento (10%) del impuesto a pagar.

Este impuesto se pagará a más tardar en el mes de mayo; a juicio de la municipalidad, podrá deducirse en la fuente en el primer trimestre del año, quedando los patronos obligados a deducirlo y enterarlo a la Municipalidad dentro de un plazo de quince (15) días después de haberse percibido.

La falta de cumplimiento a lo dispuesto en el párrafo anterior, se sancionará con una multa equivalente al veinticinco por ciento (25%) del valor dejado de retener y con el tres por ciento (3%) mensual sobre las cantidades retenidas y no enteradas en el plazo señalado; sin perjuicio de pagar las cantidades retenidas o dejadas de retener.

Se exceptúan del pago de este impuesto:

a) Quienes constitucionalmente lo estén;
b) Los jubilados y pensionados por invalidez, sobre las cantidades que reciban por estos conceptos;
c) Los ciudadanos mayores de sesenta y cinco (65) años que tuvieren ingresos brutos anuales inferiores al mínimum vital que fije la Ley del Impuesto Sobre la Renta, y;
ch) Quienes, cuando por los mismos ingresos, estén afectos en forma individual al impuesto de Industrias, comercios y Servicios

Cada año, en el mes de febrero, la Municipalidad enviará a la Dirección General de Tributación, un informe que incluya el nombre del contribuyente, su Registro Tributario Nacional y el valor declarado.

Los Diputados electos al Congreso Nacional y los funcionarios públicos con jurisdicción nacional, nombrados constitucionalmente podrán efectuar el pago del presente impuesto en el Municipio de su residencia habitual o donde ejerzan sus funciones, a su elección.','77','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":103,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c25683c534bdf1b87b3d12cc90e1ef107490b7a410773e722b91d6b42f161ab2","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','77','c25683c534bdf1b87b3d12cc90e1ef107490b7a410773e722b91d6b42f161ab2','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:78','mayalex_normativos','10_LEYES_REGLAMENTOS','Impuesto sobre Industrias, Comercios y Servicios, es el que paga mensualmente, toda persona natural o comerciante individual o social por su actividad mercantil, industrial, minera, agropecuaria, de prestación de servicios públicos y privados, de comunicación electrónica, constructoras de desarrollo urbanístico, casinos, instituciones bancarias de ahorro y préstamo, aseguradoras y toda otra actividad lucrativa, la cual tributarán de acuerdo a su volumen de producción, ingresos o ventas anuales, así:

de L.0.00 a L.500.000.00 L.0.30 por millar de L.500.001.00 a L.0.40 por
L..000.000.00 millar de a L.0.30 por
L.10.000.001.00 L.20.000.000.00 millar de a L.0.20 por
L.20.000.001.00 L.30.000.000.00 millar de en adelante L.0.15 por
L.30.000.001.00 millar

No se computarán para el cálculo de este impuesto el valor de las exportaciones de productos clasificados como no tradicionales.

Los contribuyentes a que se refiere el presente Artículo, están obligados a presentar en el mes de enero de cada año, una declaración jurada de la actividad económica del año anterior. La falta de cumplimiento de esta disposición será sancionada con una multa equivalente al impuesto correspondiente a un mes.','78','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":104,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"72a1d3eef4feb9c2a299d5db525978139a5c75a49ccf2f01eb70d614e431d2ce","ubicacion":[],"constancias":[{"nota":10,"tipo":"REFERENCIA","texto":"Según Artículo 220 de la Ley Electoral, los inmuebles de los partidos políticos están exentos de impuestos y tasas municipales.","decretos":[]},{"nota":12,"tipo":"REFERENCIA","texto":"Ver Artículo 122-A de esta Ley","decretos":[]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','78','72a1d3eef4feb9c2a299d5db525978139a5c75a49ccf2f01eb70d614e431d2ce','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:79','mayalex_normativos','10_LEYES_REGLAMENTOS','No obstante lo dispuesto en el Artículo 78, los establecimientos que a continuación se detallan, pagarán los impuestos siguientes:

1) Billares, por cada mesa pagarán mensualmente el equivalente a un salario mínimo diario;
2) La fabricación y venta de los productos sujetos a control de precios por el Estado, pagará mensualmente su impuesto, en base a sus ventas anuales de acuerdo a la escala siguiente: POR MILLAR De 0 a L. 30.000.000.00 L.0.10

De L.30.000.001.00 en adelante L.0.01

El impuesto indicado a este Artículo deberá ser pagado durante los diez (10) primeros días de cada mes, sin perjuicio del pago que por los ingresos de otros productos deberán efectuar de conformidad con lo establecido en el Artículo 78 anterior.','79','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":105,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f817cfc511dea7813379122596f3809c5b66cfa0849d7b947043aa9c78384bb9","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 177-91","decretos":["177-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','79','f817cfc511dea7813379122596f3809c5b66cfa0849d7b947043aa9c78384bb9','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:80','mayalex_normativos','10_LEYES_REGLAMENTOS','Impuesto de Extracción o Explotación de Recursos, es el que pagan las personas naturales o jurídicas que extraen o explotan canteras, minerales, hidrocarburos, bosques y sus derivados; pescan, cazan o extraen especies marítimas, lacustres o fluviales en mares y lagos, hasta 200 metros de profundidad y en ríos. La tarifa, excepto para casos contemplados en los párrafos subsiguientes, será el 1% del valor comercial de la extracción o explotación del recurso dentro del término municipal, independiente de su centro de transformación, almacenamiento, proceso o acopio, o cualquier otra disposición que acuerde el Estado.

En el caso de explotaciones minerales metálicas, además del impuesto sobre Industrias, Comercios y Servicios, se pagará a la Municipalidad por cada tonelada de material o broza procesable, en Lempiras, la suma equivalente a cincuenta centavos de Dólar de los Estados Unidos de América, conforme al Factor de Valoración Aduanera.

En caso de sal común y cal, Impuesto de Extracción o Explotación de Recursos, se pagará a partir de dos mil (2,000) toneladas métricas.

Cuando se trate de explotaciones mineras metálicas y mientras se establecen en nuestro país las refinerías para operar la separación industrial de los metales, las Municipalidades designarán el personal que estimen conveniente a los sitios de acopio o almacenamiento de material o broza procesable que mantengan las empresas, para constatar el peso de los envíos y para tomar muestras de estas, con el propósito de que aquellas, las Municipalidades, por su cuenta puedan verificar en los laboratorios nacionales o extranjeros el tipo de clase de materiales exportados.','80','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":106,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"795788e3b21d5b1e1e489cdfa22afe6fccb6a63ad1fbe08ef88ce1c56d8ea5e5","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','80','795788e3b21d5b1e1e489cdfa22afe6fccb6a63ad1fbe08ef88ce1c56d8ea5e5','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:81','mayalex_normativos','10_LEYES_REGLAMENTOS','Impuesto de Tradición de Bienes Inmuebles es el que paga el tradente al momento de efectuar la venta de un inmueble con base a su valor catastral, registrado con la tarifa siguiente:
1) Urbanos con mejoras 3%
2) Urbanos Baldíos 4%
3) Rurales con mejoras, 2%
4) Rurales baldíos 3% Efectuada la venta, el Notario insertará el testimonio respectivo, la constancia de solvencia municipal y el recibo de pago de este impuesto.','81','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":107,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"2e491a1b03f052a14ef525fd9aa3f597b5a1da0ea74884b476016c315b217e6a","ubicacion":[],"constancias":[{"nota":null,"tipo":"DEROGACION_TOTAL","texto":"Derogado según Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"derogado_por":"D.48-91","clasificacion_propuesta":{"vigencia":"DEROGADO","rol":"CONTEXT","motivo":"DEROGADO por D.48-91 según la edición AMHON (marca en línea y título de margen «DEROGADO»); la edición conserva el texto, que se mantiene como antecedente; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','81','2e491a1b03f052a14ef525fd9aa3f597b5a1da0ea74884b476016c315b217e6a','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:82','mayalex_normativos','10_LEYES_REGLAMENTOS','Impuesto Pecuario: Es el que se paga por desacate de ganado, así:

1) Por ganado mayor un salario mínimo diario, y;
2) Por ganado menor medio salario mínimo diario.

Sin perjuicio de exhibir la carta de venta en el destace de ganado mayor al momento de pagar la boleta.','82','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":108,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"6da372092422cffc03b3a19567db58516bacd06084b3ba313f9e5462ef3254c4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','82','6da372092422cffc03b3a19567db58516bacd06084b3ba313f9e5462ef3254c4','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:83','mayalex_normativos','10_LEYES_REGLAMENTOS','Servicio de Bomberos: Es el que paga toda persona individual o social, mercantil e industrial. Los ingresos por este concepto deberán ser invertidos exclusivamente, en los gastos operacionales y de mantenimiento de los cuerpos de bomberos.','83','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":109,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a5722d9ed0c5e1c2c75614058b7af88fc346cf722bb409418f61230a9c71d02d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','83','a5722d9ed0c5e1c2c75614058b7af88fc346cf722bb409418f61230a9c71d02d','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:84','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades quedan facultadas para establecer tasas por:

1) La prestación de servicios municipales directos e indirectos;
2) La utilización de bienes municipales o ejidales; y,
3) Los servicios administrativos que afecten o beneficien al habitante del término municipal.

Cada Plan de Arbitrios establecerá las tasas y demás por menores de su cobro con base en los costos reales en que incurra la Municipalidad y únicamente se podrá cobrar a quien reciba el servicio.','84','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":110,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5988e29b842138b9dc317bf200ac8b6c8d8445cb3aeb3392b30925845ecf9098","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','84','5988e29b842138b9dc317bf200ac8b6c8d8445cb3aeb3392b30925845ecf9098','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:85','mayalex_normativos','10_LEYES_REGLAMENTOS','La contribución por concepto de mejoras es la que pagarán a las Municipalidades, hasta que esta recupere total o parcialmente la inversión, los propietarios de bienes inmuebles y demás beneficiarios de obras municipales, cuando por efecto de los mismos, se produjera un beneficio para la propiedad o persona.','85','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":111,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7e3ae0fb0d2f586543112d3f84934ce07df209821cf2e3f93b423bd56dffb677","ubicacion":[],"constancias":[{"nota":13,"tipo":"INTERPRETACION_AUTENTICA","texto":"Según Decreto 171-98 se estableció lo siguiente: Artículo 5. Interpretar el artículo 85 de la Ley de Municipalidades, en el sentido que están obligados al pago de la contribución por mejoras, bajo el mecanismo de peaje, las personas que circulen en automotores en las vías públicas, cuando se trate de recuperar total o parcialmente su costo.","decretos":["171-98"]},{"nota":null,"tipo":"INTERPRETACION_AUTENTICA","texto":"Interpretado","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','85','7e3ae0fb0d2f586543112d3f84934ce07df209821cf2e3f93b423bd56dffb677','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:86','mayalex_normativos','10_LEYES_REGLAMENTOS','Facúltase a las Municipalidades para decidir sobre el porcentaje del costo de la obra o servicios a recuperar de parte de los beneficiarios, teniendo en cuenta, además del costo de la obra, las condiciones económicas y sociales de la comunidad beneficiada, y deberán las Municipalidades emitir por cada obra su propio Reglamento de Distribución y Cobro de Inversiones.

Una vez distribuido el costo de una obra o servicio entre los beneficiarios, la Municipalidad hará exigible el pago de la contribución sobre el inmueble beneficiado a su propietario, o al usuario del servicio mejorado.','86','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":112,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"77d81c0bca7f5155fd79d2f38933af66602600ff8b299b97af3f40147dffb505","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','86','77d81c0bca7f5155fd79d2f38933af66602600ff8b299b97af3f40147dffb505','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:87','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades podrán contratar empréstitos y realizar otras operaciones financieras con cualquier institución nacional, de preferencia estatal.

Cuando los empréstitos se realicen con entidades extranjeras, se seguirán los procedimientos establecidos en la Ley de Crédito Público.','87','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":113,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"bc6ddbc2018fdf9d421527b454d4e02beb46dbee6e78ca54dc618251c92696b9","ubicacion":["CAPITULO V","DE LOS CRÉDITOS Y TRANSFERENCIAS"],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','87','bc6ddbc2018fdf9d421527b454d4e02beb46dbee6e78ca54dc618251c92696b9','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:88','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades podrán emitir bonos para el financiamiento de obras y servicios, con autorización de la Secretaría de Hacienda y Crédito Público, previo dictamen favorable del Directorio del Banco Central de Honduras.','88','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":114,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7f9d75b5e9e40ac40a9664670ebe641935f191749a99df11136dcf5ee22e66a9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','88','7f9d75b5e9e40ac40a9664670ebe641935f191749a99df11136dcf5ee22e66a9','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:89','mayalex_normativos','10_LEYES_REGLAMENTOS','Los fondos obtenidos mediante empréstitos o bonos no podrán destinarse a fines distintos que para los autorizados.','89','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":115,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"052d35ce02957bb154e754156029153c5b2499c7de9aada327a1f9d0339aa20c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','89','052d35ce02957bb154e754156029153c5b2499c7de9aada327a1f9d0339aa20c','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:90','mayalex_normativos','10_LEYES_REGLAMENTOS','No se podrán dedicar al pago de empréstitos o emisión de bonos, un porcentaje superior al 20% de los ingresos ordinarios anuales de la Municipalidad, cuando se tratare de financiar obras cuya inversión no es recuperable.','90','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":116,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"0c4fac83a6013d0f536c80e28319834d3f267d394d2f1bc5b3b466866954dd89","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','90','0c4fac83a6013d0f536c80e28319834d3f267d394d2f1bc5b3b466866954dd89','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:91','mayalex_normativos','10_LEYES_REGLAMENTOS','El Estado transferirá anualmente a las municipalidades, por partidas mensuales anticipadas, de los ingresos tributarios del Presupuesto General de Ingresos y Egresos de la República y directamente de la Secretaría de Estado en el Despacho de Finanzas (SEFIN) a las cuentas de las municipalidades registradas en el sistema bancario nacional, el siete por ciento (7%) en el año 2010, el ocho por ciento (8%) en el año 2011, el nueve por ciento (9%) en el año 2012, el diez por ciento (10%) en el año 2013 y el once por ciento (11%) del año 2014 en adelante.

Este porcentaje será distribuido así:

1) Un cincuenta por ciento (50%) de la transferencia se distribuirá en partes iguales a las municipalidades; y

2) Un cincuenta por ciento (50%) será distribuido conforme a los criterios siguientes:

a) Veinte por ciento (20%) por población proyectada conforme al último Censo de

Población y Vivienda por el Instituto Nacional de Estadísticas (INE);

b) Treinta por ciento (30%) por pobreza, de acuerdo a la proporción de población pobre de cada municipio en base al método de Necesidades Básicas Insatisfechas (NBI), según el último Censo de Población y Vivienda.

De estos ingresos las municipalidades deberán destinar el uno por ciento (1%) para la ejecución y mantenimiento de programas y proyectos en beneficio de la niñez y la adolescencia, y un dos por ciento (2%) para los programas y proyectos para el desarrollo económico, social y el combate a la violencia en contra de la mujer, que se ha incrementado en forma impactante, y un trece por ciento (13%) para la operación y mantenimiento de la infraestructura social, entendiéndose comprendidas en esta última, las asignaciones necesarias para asegurar la sostenibilidad de dicha infraestructura. También podrán usar hasta el quince por ciento (15%) para gastos de administración propia; las Municipalidades cuyos ingresos propios anuales, excluidas las transferencias, no excedan de Quinientos Mil Lempiras (L.500,000.00), podrán destinar para dichos fines hasta el doble de este porcentaje.

El uno por ciento (1%) de las transferencias a que se refiere el primer párrafo de este Artículo, se destinará para el Tribunal Superior de Cuentas (TSC), como contraparte municipal para realizar las capacitaciones, seguimiento, cumplimiento a recomendaciones y una mayor cobertura de auditorías municipales. Es entendido que mientras se identifican recursos de otras fuentes para cumplir con estas obligaciones el Tribunal Superior de Cuentas (TSC), formalizará convenio con la Asociación de Municipios de Honduras (AMHON) a partir de los treinta (30) días siguientes de entrar en vigencia el presente Decreto con el propósito de planificar en forma conjunta:

1) El plan de capacitación para los municipios clasificados por la Secretaría de Estado en los Despachos de Gobernación y Justicia en las categorías A, B, C y D y de mancomunidades o asociaciones de municipios;

2) Seguimiento a recomendaciones derivadas de las auditorías municipales realizadas; y,

3) Concertar un plan de ampliación de cobertura de auditorías municipales con el fin de alcanzar el (100%) de los municipios.

El resto de los recursos de la transferencia se destinará a inversión, a cubrir la contraparte exigida por los organismos que financien los proyectos; al pago de las aportaciones a la (AMHON), al pago de las aportaciones que los municipios hacen a las mancomunidades o asociaciones previa decisión de las Corporaciones Municipales mediante el voto afirmativo de los dos tercios de sus miembros, y para transferencias en bienes o servicios a las comunidades para inversión, debiendo en todo caso respetarse lo dispuesto en el Artículo 98, numeral 6), de esta Ley.

Las municipalidades que gocen del beneficio económico establecido en el Decreto No.72- 86 de fecha 20 de mayo de 1986, podrán acogerse al régimen establecido en el presente Artículo, siempre y cuando renuncien ante la Secretaría de Estado en el Despacho de Finanzas al beneficio establecido en el Decreto antes mencionado.

La transferencia debe ingresar a la Tesorería Municipal y manejarse en cuenta bancaria a nombre de la Municipalidad respectiva, pudiendo disponerse de los recursos de la misma únicamente con la firma mancomunada y solidaria del Alcalde y Tesorero Municipal.','91','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":117,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"ec8f3119d94375df50d2e43a656ab70e6fa7c0e48e98b86172cf3a13d75c4a60","ubicacion":[],"constancias":[{"nota":14,"tipo":"REFERENCIA","texto":"Según Decreto 143-2009 se estableció lo siguiente: Artículo 3.- Forman parte de los ingresos anuales de las Municipalidades, los fondos provenientes de la Estrategia para la Reducción de la Pobreza, con el propósito de facilitar sus desembolsos y asegurarlos para que no se inviertan en otros fines que no sean para los cuales fueron creados, tomando en cuenta la Ley Especial del Fondo para la Estrategia para la Reducción de la Pobreza, que establece que estos recursos deben estar destinados exclusivamente para obras sociales y de infraestructura de las comunidades. Es obligación de los Alcaldes Municipales rendir informes a la autoridad señalada por el Poder Ejecutivo, relativos a la aplicación de los fondos, antes de iniciar la obra, y una vez concluida la misma, para la supervisión correspondiente. Para el desembolso de estos recursos se observará el mismo procedimiento establecido para el desembolso de las transferencias del Gobierno Central, indicado en el Artículo 91 de esta Ley.","decretos":["143-2009"]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 143-2009","decretos":["143-2009"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','91','ec8f3119d94375df50d2e43a656ab70e6fa7c0e48e98b86172cf3a13d75c4a60','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:92','mayalex_normativos','10_LEYES_REGLAMENTOS','El Presupuesto es el plan financiero por programas de obligatorio cumplimiento del Gobierno Municipal, que responde a las necesidades de su desarrollo y que establece las normas para la recaudación de los ingresos y la ejecución del gasto y la inversión.','92','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":118,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"15d2999892ef321eeb78002fea117f9c6b79fcf7738d6a19c35c46b127beee16","ubicacion":["CAPITULO VI","DEL PRESUPUESTO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','92','15d2999892ef321eeb78002fea117f9c6b79fcf7738d6a19c35c46b127beee16','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:93','mayalex_normativos','10_LEYES_REGLAMENTOS','El Presupuesto de Egresos debe contener una clara descripción de los programas, sub- programas, actividades y tareas, debiendo hacerse referencia en el mismo a los documentos de apoyo y consignarse las asignaciones siguientes:

1) Plan financiero completo para el año económico respectivo;
2) Un resumen general de los gastos por concepto de sueldos, salarios, jornales, materiales y equipo y obligaciones por servicios;
3) Pago a instituciones públicas, como el Instituto Hondureño de Seguridad Social, Instituto de Formación Profesional, Banco Municipal Autónomo, Instituto Nacional de Jubilaciones y Pensiones de los Empleados y Funcionarios del Poder Ejecutivo, Servicio

Nacional de Acueductos y Alcantarillados, Empresa Nacional de Energía Eléctrica u otras;
4) Los gastos a que estuviere legalmente obligado el Municipio por contratos celebrados;
5) Inversiones y Proyectos;
6) Transferencia al Cuerpo de Bomberos del Municipio;
7) Otros gastos por obligaciones contraídas; y,
8) Otros gastos de funcionamiento.','93','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":119,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"539c6e55b7f18ba3b71d54e0708320ab58b2fdfdb136f9341230191f756304e3","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','93','539c6e55b7f18ba3b71d54e0708320ab58b2fdfdb136f9341230191f756304e3','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:94','mayalex_normativos','10_LEYES_REGLAMENTOS','El Presupuesto de Ingresos deberá contener una estimación de los ingresos que se espera del período, provenientes de las fuentes siguientes:

1) Producto de los impuestos establecidos en la presente Ley;
2) Producto de las tasas y contribuciones contenidas en el Plan de Arbitrios;
3) Ingresos de Capital;
4) Producto de la venta de bienes;
5) Valor de los préstamos y convenios con bancos nacionales y extranjeros;
6) Transferencia de Capital que el Poder Ejecutivo otorgue en aplicación a la presente Ley, y del sector privado;
7) Recursos obtenidos de impuestos y recuperación de obras públicas; y,
8) Otros ingresos extraordinarios.','94','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":120,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e4d75ac965076c357fc17a4e676f35bfce97e4ca94b885d0b23ddd7bfb3c5ede","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','94','e4d75ac965076c357fc17a4e676f35bfce97e4ca94b885d0b23ddd7bfb3c5ede','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:95','mayalex_normativos','10_LEYES_REGLAMENTOS','El Presupuesto debe ser sometido a la consideración de la Corporación, a más tardar el 15 de Septiembre de cada año. Si por fuerza mayor u otras causas no estuviere aprobado el 31 de Diciembre, se aplicará en el año siguiente el del año anterior.

Para su aprobación o modificación se requiere el voto afirmativo de la mitad más uno de los miembros de la Corporación Municipal.','95','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":121,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"208931e575ff461b460c809dadd7925e217cbfc091c2b02255d087871f5669da","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','95','208931e575ff461b460c809dadd7925e217cbfc091c2b02255d087871f5669da','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:96','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Gobernación y Justicia asistirá a las Municipalidades en el sistema de codificación, nomenclatura y clasificación de cuentas del presupuesto por programas y estimación de ingresos.','96','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":122,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"78459d66d725f8cccb7cc46c330a2b5965eb3e752a77ed152a95d7d4e965a638","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','96','78459d66d725f8cccb7cc46c330a2b5965eb3e752a77ed152a95d7d4e965a638','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:97','mayalex_normativos','10_LEYES_REGLAMENTOS','Copia del presupuesto aprobado y la liquidación final correspondiente al año anterior, serán remitidas a la Secretaría de Planificación, Coordinación y Presupuesto, a más tardar el 10 de enero de cada año.','97','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":123,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d473224e06edbed2657a6685dfe6920085b2c50211aa5d51b411e68e9a5adac6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','97','d473224e06edbed2657a6685dfe6920085b2c50211aa5d51b411e68e9a5adac6','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:98','mayalex_normativos','10_LEYES_REGLAMENTOS','La formulación y ejecución del Presupuesto deberá ajustarse a las disposiciones siguientes:

1) Los egresos, en ningún caso, podrán exceder los ingresos;
2) Los gastos fijos ordinarios solamente podrán financiarse con los ingresos ordinarios de la Municipalidad;
3) Solo podrá disponerse de los ingresos extraordinarios a través de ampliaciones presupuestarias;
4) Los ingresos extraordinarios únicamente podrán destinarse a inversiones de capital;
5) No podrá contraerse ningún compromiso ni efectuarse pagos fuera de las asignaciones contenidas en el Presupuesto, o en contravención a las disposiciones presupuestarias del mismo;
6) Los gastos de funcionamiento no podrán exceder de los siguientes límites, so pena de incurrir en responsabilidad:

Ingresos Anuales Gastos de Corrientes Funcionamiento Hasta 3.000.000.00 hasta 65% De 3.000.000.01 hasta 10.000.000.00 hasta 60% De 10.000.000.01 hasta 20.000.000.00 hasta 55% De 20.000.000.01 hasta 32.000.000.00 hasta 50% De 32.000.000.01 hasta 50.000.000.00 hasta 45% De 50.000.000.01 en adelante hasta 40%

7) Los bienes y fondos provenientes de donaciones y transferencias para fines específicos, no podrán ser utilizados para finalidad diferente;
8) No podrán hacerse nombramientos ni adquirir compromisos económicos, cuando la asignación esté agotada o resulte insuficiente, sin perjuicio de la anulación de la acción y la deducción de las responsabilidades correspondientes.

La violación de lo antes dispuesto será motivo de suspensión del funcionario o empleado responsable y la reincidencia será causal de remoción.','98','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":124,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"724f90883b6f673c53580db72e08aa02ba27f5e10ec727c66fd321ee6cf46d6f","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:2"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','98','724f90883b6f673c53580db72e08aa02ba27f5e10ec727c66fd321ee6cf46d6f','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:99','mayalex_normativos','10_LEYES_REGLAMENTOS','La Municipalidad podrá crear empresas, divisiones o cualquier ente municipal desconcentrado, las que tendrán su propio presupuesto aprobado por la Corporación Municipal.

Asimismo podrá crear fondos rotatorios que custodiará el Tesorero Municipal.','99','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":125,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a1d542c0c1b6fd700a57c0579378617c7a39d5006213418e5bbdde86518dcd86","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 143-2009","decretos":["143-2009"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','99','a1d542c0c1b6fd700a57c0579378617c7a39d5006213418e5bbdde86518dcd86','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:99-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades solo podrán contratar las obras o servicios necesarios para el desarrollo del Municipio con las personas naturales o jurídicas que tengan capacidad legal para ello.

Las obras civiles municipales cuyo costo excede de CIENTO VEINTE MIL LEMPIRAS (L.120.000.00) a valores constantes del 31 de diciembre de 1999, deberán ser dirigidas por un Ingeniero Civil colegiado, a tiempo parcial. Si excediere el costo de SEISCIENTOS MIL LEMPIRAS (L.600.000.00), siempre a los mismos valores constantes, deberán ser dirigidas por un Ingeniero Civil colegiado permanente.

Queda prohibido el fraccionamiento de la obra para los efectos de la contratación.','99-A','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":126,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c3f295f9680e28cb7edc6b1835510762f6fbde4750d3347974621266a1dc9c84","ubicacion":[],"constancias":[{"nota":null,"tipo":"ADICION","texto":"Adicionado por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','99-A','c3f295f9680e28cb7edc6b1835510762f6fbde4750d3347974621266a1dc9c84','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:100','mayalex_normativos','10_LEYES_REGLAMENTOS','El Alcalde Municipal tiene la facultad de nombrar, ascender, trasladar y destituir al personal, de conformidad con la Ley, excepto los señalados en los artículos 49, 52, 56, y 59.','100','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":127,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5bf426d420ff7cd267cea121e7b3c31a73f632dfbc06a8d3bb9ebb9d875f9ba2","ubicacion":["TITULO VI","DEL PERSONAL","CAPITULO I","DE LOS EMPLEADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','100','5bf426d420ff7cd267cea121e7b3c31a73f632dfbc06a8d3bb9ebb9d875f9ba2','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:101','mayalex_normativos','10_LEYES_REGLAMENTOS','(DEROGADO POR DECRETO 149- 97 Los empleados y servidores municipales no electos se acogerán al régimen del Servicio Civil, para garantizarles estabilidad laboral.)','101','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":128,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"2192354d2e0ef72c43d749226be967d3af282657ab4d429105c4605187ac322d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','101','2192354d2e0ef72c43d749226be967d3af282657ab4d429105c4605187ac322d','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:102','mayalex_normativos','10_LEYES_REGLAMENTOS','No podrán desempeñar cargo alguno dentro de la administración municipal, cónyuges o parientes dentro del tercer grado de consanguinidad y segundo de afinidad del

Alcalde Municipal o de los miembros de la Corporación Municipal. Se exceptúan a quienes les sobrevinieren causas de incompatibilidad y los que resultaren candidatos en los casos en que hubiere concurso por oposición.','102','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":129,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e29e27dec506b6367e0d078f81d7711281a9cbbb9c79511660c33a29600dcd20","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','102','e29e27dec506b6367e0d078f81d7711281a9cbbb9c79511660c33a29600dcd20','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:103','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades están obligadas a mantener un Manual de Clasificación de Puestos y Salarios, actualizados.

Deberán, además, establecer sistemas de capacitación técnica e investigación científica, tanto para los funcionarios electos como para los nombrados, sobre diferentes actividades y programas.','103','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":130,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5cd842e455616eceed94f17c0582de2c6701e93af8158d0c20fd925e84d9af4c","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','103','5cd842e455616eceed94f17c0582de2c6701e93af8158d0c20fd925e84d9af4c','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:104','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Corporaciones Municipales podrán afiliar a su personal laborante al régimen de Jubilaciones y Pensiones de los Empleados y Funcionarios del Poder Ejecutivo, siempre y cuando sus condiciones económicas lo permitan.','104','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":131,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a19dee7df027f0a92d2e2a7555ff3c2501efbac56bde188c83be452954165dc6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','104','a19dee7df027f0a92d2e2a7555ff3c2501efbac56bde188c83be452954165dc6','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:105','mayalex_normativos','10_LEYES_REGLAMENTOS','Créase el Instituto de Desarrollo Municipal con personalidad jurídica y patrimonio propio.

El Instituto será un organismo destinado a promover el desarrollo integral de los Municipios, mediante la capacitación de los funcionarios y empleados municipales, la asesoría técnica, la promoción de la cooperación internacional y la coordinación de los entes nacionales de apoyo municipal.

Una Ley especial regulará su organización y funcionamiento.

Las municipalidades destinarán recursos propios o compartidos para su funcionamiento.','105','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":132,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"2fd5b69048106fad0ed55309662b74c21508c4eabcb90c44dbb506e78dacc0de","ubicacion":["CAPITULO II","DEL INSTITUTO DE DESARROLLO MUNICIPAL"],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','105','2fd5b69048106fad0ed55309662b74c21508c4eabcb90c44dbb506e78dacc0de','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:106','mayalex_normativos','10_LEYES_REGLAMENTOS','Las acciones que las municipalidades tuvieren en contra de particulares, provenientes de obligaciones tributarias, por los efectos de esta Ley y normas subalternas, prescribirán en el término de cinco (5) años únicamente interrumpida por acciones judiciales.','106','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":133,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"567793684942358bde7654fbceba75e8b92df556516dd268982e7788fc7f7ca5","ubicacion":["TITULO VII","DE LA PRESCRIPCIÓN","CAPITULO UNICO"],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','106','567793684942358bde7654fbceba75e8b92df556516dd268982e7788fc7f7ca5','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:107','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando la prescripción ocurriere por negligencia atribuida a funcionarios o a empleados municipales serán estos responsables de los daños y perjuicios que se hubieran ocasionado a las Municipalidades.','107','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":134,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c08825da163e510434e6165d03084f139ce646a4fa6211cfdfd28c9820def7e8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','107','c08825da163e510434e6165d03084f139ce646a4fa6211cfdfd28c9820def7e8','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:108','mayalex_normativos','10_LEYES_REGLAMENTOS','Son imprescriptibles los derechos sobre los bienes inmuebles municipales. No se podrá decretar diligencias prejudiciales ni medidas precautorias sobre los bienes inmuebles municipales.

Todo título de propiedad que otorgue la Municipalidad en cumplimiento de la política social, deberá hacerlo en forma conjunta con el cónyuge, compañera o compañero de hogar.

La certificación del acuerdo municipal será equivalente al título de propiedad y el mismo podrá inscribirse en el Registro de la Propiedad sin necesidad de escritura pública; estará exonerada del pago del Impuesto de Timbres de Contratación y del Impuesto de Tradición de Bienes Inmuebles; sin embargo, deberán cumplir con los demás requisitos registrales.

Queda prohibido al Instituto Nacional Agrario (INA), titular tierras en los núcleos de las áreas protegidas, nacionales y municipales, así como en los inmuebles de los cuales sean plenas propietarias las Municipalidades.','108','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":135,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"dfa7d3bd4f59923947fcf46414dac29692416b4c336a0cfc29fd5a440a52b2d7","ubicacion":[],"constancias":[{"nota":15,"tipo":"REFERENCIA","texto":"Según Decreto 125-2000 se estableció lo siguiente: Artículo 2.- Deberán cancelarse de oficio o a petición de cualquier interesado, en un plazo de 30 días contados a partir de la vigencia de esta Ley, las diligencias prejudiciales y las medidas precautorias dictadas en relación con los bienes inmuebles municipales.","decretos":["125-2000"]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 125-2000","decretos":["125-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','108','dfa7d3bd4f59923947fcf46414dac29692416b4c336a0cfc29fd5a440a52b2d7','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:109','mayalex_normativos','10_LEYES_REGLAMENTOS','El atraso en el pago de cualquier tributo municipal dará lugar al pago de un interés anual, igual a la tasa que los bancos utilizan en sus operaciones comerciales activas, más un recargo del dos por ciento (2%) anual calculado sobre saldos.','109','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":136,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c1cbde35fc5e14840644956f586d5f50bc8b0c1f418032b89d0790bfca36df7e","ubicacion":["TITULO VIII","DE LAS DISPOSICIONES GENERALES"],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','109','c1cbde35fc5e14840644956f586d5f50bc8b0c1f418032b89d0790bfca36df7e','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:110','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades podrán recibir anticipadamente el pago de los tributos municipales; en estos casos deberán rebajar el diez por ciento (10%) del total; asimismo en casos especiales tales como caso fortuito o fuerza mayor, prorrogarán el período de cobro hasta por treinta días o hasta que cesen las causas que hubieren generado la calamidad o emergencia. El beneficio del pago anticipado solo será aplicable cuando se efectúe cuatro meses antes de la fecha legal del pago.','110','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":137,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7edfffc93756120a7611b3b87f8a0233b78b37c25b00f84b1db276b538b1f5f0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','110','7edfffc93756120a7611b3b87f8a0233b78b37c25b00f84b1db276b538b1f5f0','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:111','mayalex_normativos','10_LEYES_REGLAMENTOS','Toda deuda proveniente del pago del Impuesto de Bienes Inmuebles, industria, comercio, servicios, contribución por mejoras constituye un crédito preferente a favor de la Municipalidad y para su reclamo judicial se procederá por la vía ejecutiva. Servirá de Título Ejecutivo la certificación del monto adeudado, extendido por el Alcalde Municipal.','111','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":138,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"3b23a817a928cab54371eedd02b5fe67f7426c9397a3ccc8d2c091f84176a1c6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','111','3b23a817a928cab54371eedd02b5fe67f7426c9397a3ccc8d2c091f84176a1c6','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:112','mayalex_normativos','10_LEYES_REGLAMENTOS','La morosidad en el pago de los impuestos establecidos en esta Ley, dará lugar a que la Municipalidad ejercite para el cobro, la vía de apremio judicial, previo a dos requerimientos por escrito a intervalos de un mes cada uno y después podrá entablar contra el contribuyente deudor el Juicio Ejecutivo correspondiente, sirviendo de Título Ejecutivo la certificación de falta de pago, extendida por el Alcalde Municipal.','112','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":139,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"0fe972c6ea66493ef9dbe8bc944f5480eab602a0c4c2a6e296a35286276e4a54","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','112','0fe972c6ea66493ef9dbe8bc944f5480eab602a0c4c2a6e296a35286276e4a54','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:113','mayalex_normativos','10_LEYES_REGLAMENTOS','Los inmuebles garantizarán el pago de los impuestos que recaigan sobre los mismos, sin importar el cambio de propietario que sobre ellos se produzca, aun cuando se refieran a remates judiciales o extrajudiciales, los nuevos dueños deberán cancelar dichos impuestos, previa inscripción en el Registro de la Propiedad.','113','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":140,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5693e6bb3e4e30aedb45deefe4a5a7caac7a505987a60c0273769e6241e47e8d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','113','5693e6bb3e4e30aedb45deefe4a5a7caac7a505987a60c0273769e6241e47e8d','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:114','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Corporaciones Municipales, tendrán la obligación de responder en cabildo abierto en forma inmediata a las peticiones que sobre su gestión planteen los que concurran a la misma; y en caso de gestión particular distinta, deberán resolver en el plazo de quince días.','114','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":141,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7639ddb671118cc3af32851c0396364531a85d9ecac7b1c5dc9a05efcd7655c2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','114','7639ddb671118cc3af32851c0396364531a85d9ecac7b1c5dc9a05efcd7655c2','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:115','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades, cuando sus recursos lo permitan, están obligadas a publicar la Gaceta Municipal donde consten sus resoluciones más relevantes, un resumen del presupuesto, su liquidación y la respuesta a las solicitudes de rendición de cuenta. La edición de la Gaceta Municipal se hará por los menos semestralmente. La forma de su emisión queda sujeta a la capacidad económica de las Municipalidades.','115','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":142,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d62443985843b8c6ae2c6eb916608f40a921c8712e850517ce54dad59cdda907","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','115','d62443985843b8c6ae2c6eb916608f40a921c8712e850517ce54dad59cdda907','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:116','mayalex_normativos','10_LEYES_REGLAMENTOS','Para financiar la publicación de la Gaceta Municipal, todo vecino del término respectivo podrá adquirirla al precio que se fije en el Plan de Arbitrios.

Además, las Municipalidades pueden vender espacios para publicidad, a efectos de financiar sus costos.','116','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":143,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"741bb58f7b468018ff796c4478d7b30257735a2902b83c7bc05b44f804644f14","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','116','741bb58f7b468018ff796c4478d7b30257735a2902b83c7bc05b44f804644f14','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:117','mayalex_normativos','10_LEYES_REGLAMENTOS','Son motivos de utilidad pública e interés social, para decretar la expropiación total o parcial de predios, además de los determinados en las leyes vigentes, las obras de seguridad, ornato, embellecimiento de barrios, apertura o ampliación de calles, carreteras, edificaciones para mercados, plazas, parques, jardines públicos, áreas de recreo y deportes, construcción de terminales de transporte urbano e interurbano, centros educativos, clínicas y hospitales, represas, sistemas de agua potable y su tratamiento, así como, de desechos sólidos, zonas de oxigenación, áreas para la urbanización de protección a la biodiversidad, cuencas y sus afluentes y otras obras públicas de necesidad comunitaria o municipal calificadas por la Corporación Municipal. Excepcionalmente para los mismos fines, podrá adquirir inmuebles mediante contratación directa, por su valor catastral, cuando no hubiese otros disponibles, debiendo dejar evidencia de estas circunstancias.

Para proceder a la expropiación se observarán los procedimientos establecidos en la Constitución de la República y en la Ley de Expropiación Forzosa en lo que fueren aplicables. Sobre los predios del Estado, del municipio o sobre aquellos en que los particulares únicamente tengan dominio útil, solo se reconocerá el valor de las mejoras.

La Corporación también podrá gravar con servidumbres los bienes de propiedad privada, siempre que la utilización del inmueble a gravarse sea necesaria para la prestación de un servicio público. Las servidumbres, incluirán, además, el derecho de inspeccionar el inmueble y de ingresar al mismo para efectuar las reparaciones que fuesen necesarias para la prestación del servicio.','117','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":144,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"24b90a4240ad6298e5b8a5ef22e80a0629b9a20bada2c485990591a2d76653f5","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','117','24b90a4240ad6298e5b8a5ef22e80a0629b9a20bada2c485990591a2d76653f5','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:118','mayalex_normativos','10_LEYES_REGLAMENTOS','La ejecución de planes de desarrollo urbano y la constitución de reservas para futuras extensiones de las ciudades, o para la protección del sistema ecológico, son de utilidad pública e interés social.

La Secretaría de Estado en los Despachos de Gobernación y Justicia, a través de la Dirección General de Asistencia Técnica Municipal, colaborará con las municipalidades para el cumplimiento de lo dispuesto en este Artículo y para la delimitación del perímetro urbano.

Los planes relacionados con las expansiones futuras de las ciudades serán sometidos a la aprobación del Poder Ejecutivo.','118','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":145,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"ed994039fcb27647571475044361c0cbfb7c3687dbe33323a12f3071e0069862","ubicacion":[],"constancias":[{"nota":16,"tipo":"DEROGACION_PARCIAL","texto":"Este párrafo fue Derogado por el Artículo 4 del Decreto 127-2000)","decretos":["127-2000"]},{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 48-91","decretos":["48-91"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (derogación parcial anotada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','118','ed994039fcb27647571475044361c0cbfb7c3687dbe33323a12f3071e0069862','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:119','mayalex_normativos','10_LEYES_REGLAMENTOS','La Corporación Municipal podrá ocurrir a la Secretaría de Estado en los Despachos de Gobernación y Justicia, en apelación de resoluciones, acuerdos, disposiciones, actos u órdenes de la Gobernación Departamental u otra autoridad cuando lesionen el interés municipal. Esta Secretaría de Estado tendrá el plazo que señala el Artículo 138 de la Ley de Procedimiento Administrativo para resolver lo pertinente.','119','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":146,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"be9402c6c01d97bc528288974e504686bd6af3d6be964da9c6dd8e0cb7af23c4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','119','be9402c6c01d97bc528288974e504686bd6af3d6be964da9c6dd8e0cb7af23c4','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:120','mayalex_normativos','10_LEYES_REGLAMENTOS','Toda ejecución de obras y servicios públicos o inversiones de desarrollo en el término municipal, que proyecte cualquier entidad estatal, privada u Organización No Gubernamental (ONG’s) y otras similares, deberá estar en armonía con el Plan de Desarrollo Municipal y en coordinación con la Corporación Municipal.','120','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":147,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e728f54ad29f5638d1cfb47342e3d2df576e5905c9ef596b7015f3c43b766e8f","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 143-2009","decretos":["143-2009"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','120','e728f54ad29f5638d1cfb47342e3d2df576e5905c9ef596b7015f3c43b766e8f','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:121','mayalex_normativos','10_LEYES_REGLAMENTOS','Salvo lo autorizado en la presente Ley, las Municipalidades no podrán condonar los tributos, sus multas la mora o cualquier recargo, no obstante quedan facultadas para establecer planes de pago.','121','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":148,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"8f493c71c8926e690759ca726bda04571bc23c6d49a47c8c9f1432eb366daf5d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','121','8f493c71c8926e690759ca726bda04571bc23c6d49a47c8c9f1432eb366daf5d','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:122','mayalex_normativos','10_LEYES_REGLAMENTOS','La Dirección Ejecutiva de Ingresos (DEI), está obligada a extender de oficio a las Municipalidades el respectivo carnet de exención de impuestos de ventas y a proporcionar por escrito a las Municipalidades, toda la información relativa a los ingresos tributarios y su comportamiento trimestral, lo mismo que la demás información que requiera sobre el patrimonio o ingresos de las personas naturales o jurídicas de su territorio para efectos de tributo, debiendo respetarse en todo caso el derecho de intimidad. Igual obligación de información tendrá el Banco Central de Honduras.','122','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":149,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"23280c125af9e0b0cceb1e323effaffac07b582e4778949c62b4cb1fb029b795","ubicacion":[],"constancias":[{"nota":null,"tipo":"REFORMA","texto":"Según reforma por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','122','23280c125af9e0b0cceb1e323effaffac07b582e4778949c62b4cb1fb029b795','OLA13_LMUN_2009_01',now()),
('OLA13_LMUN_2009_01:LEY_MUNICIPALIDADES:122-A','mayalex_normativos','10_LEYES_REGLAMENTOS','Las instituciones descentralizadas que realicen actividades económicas, los procesadores y revendedores de café y demás cultivos no tradicionales, están obligados al pago de los impuestos municipales correspondientes por el valor agregado que generen. Asimismo, están obligados al pago de las tasas por los servicios que preste, derechos por licencias y permisos y de las contribuciones municipales.

También podrán imponer tasas y contribuciones por los servicios que presten en materia de preservación del ambiente.

Los montos pagados en concepto de impuestos, tasas, derechos y contribuciones declarados por los contribuyentes más los ajustes introducidos por la Administración Tributaria de las municipalidades, serán ingresados inmediatamente en la Tesorería Municipal. Las devoluciones por el pago de las acciones tributarias especificadas en el párrafo anterior que resulten de los ajustes correspondientes, se efectuarán por las municipalidades a más tardar, dentro de los quince (15) días siguientes a la fecha en que se reconoció tal devolución.

Cuando en el ejercicio de la acción tributaria existiera duda sobre la veracidad de las declaraciones, para efecto del pago de los impuestos, tasas, derechos, o contribuciones municipales, o cuando el contribuyente niegue tal obligación, el Alcalde de acuerdo al dictamen de la administración tributaria, procederá de oficio a tasar dichos impuestos, tasas, derechos y contribuciones.','122-A','Ley de Municipalidades de Honduras (Decreto No. 134-90)','{"norm_id":"HN:LEY_MUNICIPALIDADES","instrumento_id":"LEY_MUNICIPALIDADES","ingest_batch":"OLA13_LMUN_2009_01","ola":"OLA13","ordinal":150,"decreto":"134-90","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), con reformas integradas hasta el D.143-2009 marcadas en línea y 16 notas al pie; sin el Reglamento General (Acuerdo 018-93).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"24a74eb68d4004b111565e48a74178169b944d334db73ddb3ef92b93b4263bc6","ubicacion":[],"constancias":[{"nota":null,"tipo":"ADICION","texto":"Adicionado por Decreto 127-2000","decretos":["127-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","MARCAS_EN_LINEA_A_CONSTANCIAS:1"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada AMHON con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_MUNICIPALIDADES','122-A','24a74eb68d4004b111565e48a74178169b944d334db73ddb3ef92b93b4263bc6','OLA13_LMUN_2009_01',now())
